-- dsl-10-check-build-plan.commit.sql
--
-- ============================== COMMIT - THIS WRITES ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. Run the preflight first.
--
-- WHAT THIS ADDS: the build plan of flight dsl-check-capability-feature-conformance-build (work class owner-objective) under planner agent
-- claude-code-opus-5-5-dsl-check-build, through the installed writer evidence.upsert_flight_plan. It approves nothing and flies nothing.
-- Re-running is harmless. The plan is flights/check-build.steps.json; its digest is
-- sha256:7144d15fe432b8cb32624a007dc440a4aee1798498ce9c8c2c7cc3539255e3a4.
-- OV3 flies four steps: it installs analysis.check_capability_feature_conformance from the source sql/dsl-09 retained, with apply-engineering-change
-- and EXECUTE for the reader, and proves its definition (sha256:ffd7c3a98c237784fcf6dd3b0b4f5e8414d728965e8aaf4f048ad43fe066a924); it declares check-capability-feature-conformance from
-- conformance/check-capability-feature-conformance.dsl with capability-from-dsl, which binds the retained bytes of the
-- canonical feature and commits only when the check finds the binding CONFORMANT, and proves the declared feature pin.
-- RUN dsl-07 AND dsl-09 FIRST.
-- WHERE: the sfx-identity database. GUARD: the writer has its four parameters and the owner principal is active.
-- RESULT SETS: guard; plans (plan_revision, matches_reviewed_file 1).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @params int=(SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'evidence.upsert_flight_plan') AND name IN (N'@principal_id',N'@agent_id',N'@objective',N'@steps_json'));
DECLARE @active int=(SELECT COUNT(*) FROM [identity].principal WHERE principal_id='565de6d4-ebcd-408b-9359-04d21dc62183' AND active=1);
SELECT N'guard' AS result_set,@params AS writer_parameters,4 AS expected_parameters,@active AS owner_principal_active;
IF @params<>4 OR @active<>1
BEGIN
 RAISERROR(N'DSL10_PLAN_GUARD: the plan writer or the owner principal is not as reviewed; nothing was recorded.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
DECLARE @p uniqueidentifier='565de6d4-ebcd-408b-9359-04d21dc62183';
DECLARE @r TABLE(plan_revision bigint,plan_digest binary(32),updated_at datetime2(7));
INSERT @r EXEC evidence.upsert_flight_plan @principal_id=@p,@agent_id=N'claude-code-opus-5-5-dsl-check-build',@objective=N'Install analysis.check_capability_feature_conformance and declare check-capability-feature-conformance feature first, through OV3''s own changes: install the procedure from its retained source with apply-engineering-change and prove its definition, then declare the capability from its DSL with capability-from-dsl, which binds the retained bytes of its canonical feature and commits only when the check finds the binding CONFORMANT, and prove the declaration keeps that feature pin.',
 @steps_json=N'[{"stepId":"plan-header","contractId":"estate-flight-plan.v1","promiseId":"dsl-check-capability-feature-conformance-build","flightType":"execution","workClass":"owner-objective","unknowns":[]},{"stepId":"install-procedure","capabilityId":"apply-engineering-change","historicalBasis":"ledger 7df11b46-3dce-4fa2-9d65-6326c481650b (2026-11-02T02:50:11.355): analysis.objective_agent_step installed by apply-engineering-change, one of 238 applied engineering changes (run fc518bd3); this source, retained under its digest by sql/dsl-09, met the probed cases of its canonical feature read-only through sql-database-reader (runs 5fae01e0, 31062d0e, 2df0fbf8, f31ee728) and holds none of the installer''s refused tokens","input":{"contractId":"engineering-change.v1","sourceDigest":"sha256:e1afc4f75e34b69e32b605a553235e5abcc78a22997b12ac8b545d995615adfe","mode":"commit","note":"Install analysis.check_capability_feature_conformance, the no-drift check of the canonical features (dsl-capabilities-for-ov3-workflow-spec).","grantExecuteOn":["analysis.check_capability_feature_conformance"],"verificationCapabilityId":"read-harness-authoring-state","preflight":{"input":{"changeKind":"engineering-change","includeDefinitions":true},"expected":{"disposition":"terminated"}},"route":{"resolvedDisposition":"terminated"}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-procedure","capabilityId":"read-declared-object-source","historicalBasis":"read-declared-object-source reports analysis.fv_object_definition_digest; each of the six newest procedure installs kept its retained source with CREATE OR ALTER PROCEDURE stored as CREATE PROCEDURE and every other byte unchanged (run 9e384ab2), so this source installs as this digest","input":{"objectName":"analysis.check_capability_feature_conformance"},"obligationIds":["O1"],"expect":{"path":"$.definitionDigest","equals":"sha256:ffd7c3a98c237784fcf6dd3b0b4f5e8414d728965e8aaf4f048ad43fe066a924"}},{"stepId":"declare-capability","capabilityId":"apply-declared-change","historicalBasis":"ledger 8704fa02-098a-4109-9c6c-bdbabbdc1cdc (2026-11-02T05:22:29.712): capture-estate-live-observation declared by capability-from-dsl (scaffold CREATE), one of 412 committed declarations (run fc518bd3); this DSL compiles COMPILED against the retained bytes of its feature with the revised compiler (run 8b8b7e11), and sql/dsl-06-test.sql declared a pinned probe through the revised author path, bound its feature and found it CONFORMANT","input":{"contractId":"declared-change.v1","changeKind":"capability-from-dsl","payload":{"contractId":"capability-from-dsl-change.v1","source":"capability check-capability-feature-conformance\nfeature check-capability-feature-conformance sha256:49bf06230349e792eeba7041a7f7ecf2cd2c894aa5635ae2ec5c5b2130ab02b9\nintent: Check a capability''s circuit against its canonical feature by identity, and accept each case only from the pinned evidence of its own call\noutcome: capability-feature-conformance.v1 CONFORMANT, DRIFT, WELL_FORMED, MALFORMED, NOT_BOUND, NOT_FOUND, ACCEPTED, REJECTED or BASELINE, with each finding named by its code and identity\ninquiry: Does this capability''s circuit drift from its canonical feature?\ninquiry: Which identity, step or case drifted, and where?\ninquiry: Does this run prove this case through its own call?\ninput contract check-capability-feature-conformance-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"capabilityId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":400},\"featureText\":{\"type\":\"string\",\"minLength\":1},\"featureDigest\":{\"type\":\"string\",\"pattern\":\"^sha256:[0-9a-f]{64}$\"},\"document\":{\"type\":\"object\"},\"acceptance\":{\"type\":\"object\"},\"evidenceText\":{\"type\":\"string\",\"minLength\":1},\"baseline\":{\"type\":\"object\"},\"explain\":{\"type\":\"boolean\"}}}\noutput contract capability-feature-conformance.v1 {\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"contractId\",\"status\"],\"properties\":{\"contractId\":{\"const\":\"capability-feature-conformance.v1\"},\"status\":{\"type\":\"string\"}}}\ncli display outcome as json\nscenario check-capability-feature-conformance root terminal\nvariants: CONFORMANT:success,DRIFT:success,WELL_FORMED:success,MALFORMED:success,NOT_BOUND:success,NOT_FOUND:success,ACCEPTED:success,REJECTED:success,BASELINE:success\ngiven: a capability of the selected estate, a feature text, or an acceptance record with the run evidence it pins\nwhen: the feature is parsed scope by scope and each identity, step and case is compared with its declaration or with the evidence of its own call\nthen: CONFORMANT, WELL_FORMED or ACCEPTED, or each drift named by its code and identity\noperation check-capability-feature-conformance.check uses provider sql-database-reader\nconfig: {\"dataSource\":\"sfx-estate-database\",\"statement\":\"SET ARITHABORT ON; DECLARE @estate_model_pk bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1); EXEC analysis.check_capability_feature_conformance @input=@input,@estate_model_pk=@estate_model_pk;\",\"resultColumn\":\"value\"}\ninput input from check-capability-feature-conformance $\noutcome from check-capability-feature-conformance.check $.value\n","isMcpTooling":true,"verificationCapabilityId":"read-harness-authoring-state","preflight":{"input":{"changeKind":"capability-from-dsl","includeDefinitions":true},"expected":{"disposition":"terminated"}},"route":{"resolvedDisposition":"terminated"}}},"obligationIds":["O2"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-declared","capabilityId":"read-declared-capability-document","historicalBasis":"read-declared-capability-document returns the stored compiled document (run 6d338754, compile-capability-dsl, document sha256:55ccc6fe...); a declaration stores the whole document by digest, and sql/dsl-06-test.sql found the feature pin kept in it","input":{"capabilityId":"check-capability-feature-conformance"},"obligationIds":["O2"],"expect":{"path":"$.document.feature.digest","equals":"sha256:49bf06230349e792eeba7041a7f7ecf2cd2c894aa5635ae2ec5c5b2130ab02b9"}}]';
SELECT N'plans' AS result_set,N'claude-code-opus-5-5-dsl-check-build' AS agent_id,plan_revision,N'sha256:'+LOWER(CONVERT(varchar(64),plan_digest,2)) AS plan_digest,CASE WHEN plan_digest=CONVERT(binary(32),'0x7144d15fe432b8cb32624a007dc440a4aee1798498ce9c8c2c7cc3539255e3a4',1) THEN 1 ELSE 0 END AS matches_reviewed_file,updated_at FROM @r;
COMMIT TRANSACTION;
GO
SET NOEXEC OFF;
